[{"agent": "coding_agent", "event": "call", "tool": "save_code", "arguments": {"code": "/*
  Two-Wheel Obstacle Avoiding Robot
  Hardware:
  - Arduino Uno/Nano
  - L298N Motor Driver
  - HC-SR04 Ultrasonic Sensor
  - 2x DC Motors with wheels
  - Chassis, battery, etc.

  Wiring:
  HC-SR04:
    VCC -> 5V
    GND -> GND
    Trig -> Pin 8
    Echo -> Pin 7

  L298N Motor Driver:
    12V -> Battery Positive
    GND -> Battery Negative & Arduino GND
    IN1 -> Pin 5 (Left Motor Forward)
    IN2 -> Pin 4 (Left Motor Backward)
    ENA -> Pin 3 (Left Motor Speed PWM)
    IN3 -> Pin 12 (Right Motor Forward)
    IN4 -> Pin 13 (Right Motor Backward)
    ENB -> Pin 11 (Right Motor Speed PWM)
*/

// Ultrasonic Sensor Pins
const int trigPin = 8;
const int echoPin = 7;

// Left Motor Pins
const int leftMotorForward = 5;
const int leftMotorBackward = 4;
const int leftMotorSpeed = 3;

// Right Motor Pins
const int rightMotorForward = 12;
const int rightMotorBackward = 13;
const int rightMotorSpeed = 11;

// Obstacle distance threshold in cm
const int obstacleDistance = 20;

void setup() {
  // Set motor pins as outputs
  pinMode(leftMotorForward, OUTPUT);
  pinMode(leftMotorBackward, OUTPUT);
  pinMode(leftMotorSpeed, OUTPUT);

  pinMode(rightMotorForward, OUTPUT);
  pinMode(rightMotorBackward, OUTPUT);
  pinMode(rightMotorSpeed, OUTPUT);

  // Set ultrasonic sensor pins
  pinMode(trigPin, OUTPUT);
  pinMode(echoPin, INPUT);

  // Initialize serial for debugging (optional)
  Serial.begin(9600);
}

void loop() {
  long duration, distance;

  // Send a 10us pulse to trigger the sensor
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);

  // Read the echo pin and calculate distance
  duration = pulseIn(echoPin, HIGH);
  distance = (duration / 2) / 29.1; // Convert to cm

  Serial.print("Distance: ");
  Serial.print(distance);
  Serial.println(" cm");

  if (distance > obstacleDistance) {
    // No obstacle, move forward
    moveForward();
  } else {
    // Obstacle detected
    stopRobot();
    delay(300);

    // Move backward slightly
    moveBackward();
    delay(500);

    // Turn right to avoid obstacle
    turnRight();
    delay(700);

    // Resume moving forward
    moveForward();
  }
}

void moveForward() {
  digitalWrite(leftMotorForward, HIGH);
  digitalWrite(leftMotorBackward, LOW);
  analogWrite(leftMotorSpeed, 200); // Speed 0-255

  digitalWrite(rightMotorForward, HIGH);
  digitalWrite(rightMotorBackward, LOW);
  analogWrite(rightMotorSpeed, 200);
}

void moveBackward() {
  digitalWrite(leftMotorForward, LOW);
  digitalWrite(leftMotorBackward, HIGH);
  analogWrite(leftMotorSpeed, 150);

  digitalWrite(rightMotorForward, LOW);
  digitalWrite(rightMotorBackward, HIGH);
  analogWrite(rightMotorSpeed, 150);
}

void turnRight() {
  // Left motor forward, right motor backward
  digitalWrite(leftMotorForward, HIGH);
  digitalWrite(leftMotorBackward, LOW);
  analogWrite(leftMotorSpeed, 180);

  digitalWrite(rightMotorForward, LOW);
  digitalWrite(rightMotorBackward, HIGH);
  analogWrite(rightMotorSpeed, 180);
}

void turnLeft() {
  // Left motor backward, right motor forward
  digitalWrite(leftMotorForward, LOW);
  digitalWrite(leftMotorBackward, HIGH);
  analogWrite(leftMotorSpeed, 180);

  digitalWrite(rightMotorForward, HIGH);
  digitalWrite(rightMotorBackward, LOW);
  analogWrite(rightMotorSpeed, 180);
}

void stopRobot() {
  digitalWrite(leftMotorForward, LOW);
  digitalWrite(leftMotorBackward, LOW);
  analogWrite(leftMotorSpeed, 0);

  digitalWrite(rightMotorForward, LOW);
  digitalWrite(rightMotorBackward, LOW);
  analogWrite(rightMotorSpeed, 0);
}", "filename": "obstacle_avoiding_robot.ino"}, "tool_call_id": "ybkazxyy4"}, {"agent": "coding_agent", "event": "result", "tool": "save_code", "content": "{"saved": true, "path": "/Users/rayentabet/Desktop/InMind/Assignment_10/generated/code/obstacle_avoiding_robot.ino"}", "tool_call_id": "ybkazxyy4"}, {"agent": "coding_agent", "event": "call", "tool": "validate_code", "arguments": {"filename": "obstacle_avoiding_robot.ino"}, "tool_call_id": "95jneevjd"}, {"agent": "coding_agent", "event": "result", "tool": "validate_code", "content": "{"valid": true, "errors": []}", "tool_call_id": "95jneevjd"}, {"agent": "robot_visualization_agent", "event": "call", "tool": "save_openscad", "arguments": {"model_name": "robot_model", "code": "// Robot Chassis
